// Extrai e padroniza os detalhes do erro capturado
const execution = $json.execution;
const workflowInfo = $json.workflow;
const trigger = $json.trigger;

const nodeComErro = execution?.error?.node?.name || "Nó não identificado";
const mensagemErro = execution?.error?.message || "Mensagem de erro não disponível";
const tipoErro = execution?.error?.name || "Erro genérico";

// Nós considerados críticos: qualquer falha aqui pode comprometer
// integridade de dados sensíveis (LGPD) ou perda de registro de caso
const nosCriticos = [
  "Code - Mascaramento Definitivo LGPD",
  "Google Sheets - Aplicar Mascaramento",
  "Google Sheets - Registrar Caso",
  "Google Sheets - Log Imutável de Auditoria",
  "Google Sheets - Atualizar Status"
];

const critico = nosCriticos.some(n => nodeComErro.includes(n));

return {
  json: {
    workflow_com_erro: workflowInfo?.name || "Desconhecido",
    workflow_id: workflowInfo?.id || "",
    node_com_erro: nodeComErro,
    tipo_erro: tipoErro,
    mensagem_erro: mensagemErro,
    critico,
    data_hora_erro: new Date().toISOString(),
    execution_url: execution?.url || ""
  }
};

