// Monta o checklist de revisão periódica de credenciais
// (n8n não expõe data de expiração de token via API pública de forma
// padronizada para todos os provedores, então este nó gera um lembrete
// estruturado para revisão manual/registrada pelo responsável)

const credenciais = [
  { nome: "Google Sheets OAuth2", projeto: "n8n-grp-automacoes", tipo: "OAuth2" },
  { nome: "Google Drive OAuth2", projeto: "n8n-grp-automacoes", tipo: "OAuth2" },
  { nome: "Gmail OAuth2", projeto: "n8n-grp-automacoes", tipo: "OAuth2" },
  { nome: "Slack Bot Token", projeto: "GRP Compliance Teste", tipo: "Bot Token" }
];

const dataAtual = new Date().toISOString().split("T")[0];
const listaFormatada = credenciais
  .map(c => `• ${c.nome} (${c.tipo}) — projeto/workspace: ${c.projeto}`)
  .join("\n");

return {
  json: {
    data_revisao: dataAtual,
    total_credenciais: credenciais.length,
    checklist: listaFormatada
  }
};

